import{_ as e,o,c as d,a2 as a}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"CC Switch 接入 Claude Desktop（桌面版）：Windows 和 Mac 都能用中转站","description":"","frontmatter":{"title":"CC Switch 接入 Claude Desktop（桌面版）：Windows 和 Mac 都能用中转站","date":"2026-09-18T20:00:00.000Z","tags":["CC Switch","Claude Desktop","中转站","教程"],"categories":["技术折腾"]},"headers":[],"relativePath":"guide/04-claude-desktop.md","filePath":"guide/04-claude-desktop.md"}'),l={name:"guide/04-claude-desktop.md"};function s(i,t,r,n,c,u){return o(),d("div",null,[...t[0]||(t[0]=[a('<blockquote><p>生命不息，折腾不止。</p></blockquote><p>Claude Desktop 是 Anthropic 的桌面图形客户端（支持 MCP 能力那个）。这篇教小白：在 Windows 和 Mac 上装好 Claude Desktop，再用 CC Switch 把 AI 中转站接进去——<strong>和 Codex 桌面版一个道理：Claude Desktop 界面里没有切换供应商的按钮，想用中转站，CC Switch 几乎是必须的</strong>。</p><h2 id="一、claude-desktop-是个啥" tabindex="-1">一、Claude Desktop 是个啥 <a class="header-anchor" href="#一、claude-desktop-是个啥" aria-label="Permalink to &quot;一、Claude Desktop 是个啥&quot;">​</a></h2><p>Claude Desktop 是一个<strong>图形窗口的聊天客户端</strong>，装好就是一个应用，打开就能跟 Claude 对话，还支持 MCP（连外部工具）。</p><p><strong>两个容易搞混的东西：</strong></p><table tabindex="0"><thead><tr><th></th><th>Claude Code（CLI）</th><th>Claude Desktop（桌面版）</th></tr></thead><tbody><tr><td>形态</td><td>终端命令行</td><td>图形窗口应用</td></tr><tr><td>配置位置</td><td><code>~/.claude/settings.json</code></td><td>独立的 3P profile</td></tr><tr><td>CC Switch 里显示</td><td>「Claude」</td><td>「Claude Desktop」</td></tr></tbody></table><p><strong>支持平台：</strong> macOS（需 Apple Silicon）和 Windows；Linux 暂不支持写入 Claude Desktop 配置（Linux 用 CLI 版）。</p><p><strong>关键点（和 Codex 桌面版一样）：</strong> Claude Desktop 的界面里<strong>没有切换供应商的按钮</strong>，它只认电脑里的 3P profile 配置。想用中转站？就得有人帮你改配置——这个人就是 CC Switch。</p><h2 id="二、准备工作" tabindex="-1">二、准备工作 <a class="header-anchor" href="#二、准备工作" aria-label="Permalink to &quot;二、准备工作&quot;">​</a></h2><blockquote></blockquote><p>（2 分钟）</p><ol><li><strong>中转站 API Key</strong>：登录你的中转站（如 ai.aklibk.com）→ 后台 → API Keys → 创建，复制 <code>sk-</code> 开头的 Key</li><li><strong>下载 Claude Desktop</strong>：去 Claude 官网下载 macOS / Windows 安装包，装好</li><li><strong>下载 CC Switch</strong>：官网 ccswitch.io 或 GitHub Releases（只认官方渠道！）</li></ol><h2 id="三、在-cc-switch-里添加-claude-desktop-供应商" tabindex="-1">三、在 CC Switch 里添加 Claude Desktop 供应商 <a class="header-anchor" href="#三、在-cc-switch-里添加-claude-desktop-供应商" aria-label="Permalink to &quot;三、在 CC Switch 里添加 Claude Desktop 供应商&quot;">​</a></h2><p><strong>最省事的路径（推荐）：一键导入</strong></p><p>如果你已经在 CC Switch 的 Claude Code（CLI）里配过中转站，直接切到 <strong>Claude Desktop</strong> 面板，点 <strong>「将 Claude Code 中已有的供应商导入」</strong>——几秒钟复制过来，不用重新填。</p><p><strong>或者手动添加：</strong></p><ol><li>打开 CC Switch，左侧切换器选 <strong>Claude Desktop</strong></li><li>点右上角 <strong>+</strong> 号</li><li>预设选 <strong>自定义</strong>（或选一个中转服务预设）</li><li>填关键信息： <ul><li><strong>名称</strong>：如 <code>我的中转站</code></li><li><strong>API 地址（Base URL）</strong>：<code>https://ai.aklibk.com</code>（以中转站文档为准）</li><li><strong>API Key</strong>：粘贴中转站的 Key</li></ul></li><li><strong>关键一步：「需要模型映射」开关</strong><ul><li>模型是 <code>claude-sonnet-*</code> / <code>claude-opus-*</code> / <code>claude-haiku-*</code> 官方三档 → <strong>关掉</strong>（直连模式）</li><li>模型是 DeepSeek / Kimi / GLM 等国产模型、或旧式 Claude ID → <strong>打开</strong>（CC Switch 本地网关帮你映射成 Sonnet/Opus/Haiku）</li></ul></li><li>点 <strong>添加</strong>，再点一下这个供应商（选中 = 生效）</li></ol><blockquote></blockquote><h2 id="四、切换并打开-claude-desktop" tabindex="-1">四、切换并打开 Claude Desktop <a class="header-anchor" href="#四、切换并打开-claude-desktop" aria-label="Permalink to &quot;四、切换并打开 Claude Desktop&quot;">​</a></h2><ol><li>确认 CC Switch 里选中了你刚加的中转站供应商</li><li><strong>重启 Claude Desktop</strong>（关键！重启才会读新配置）</li><li>打开 Claude Desktop 窗口，随便问一句</li></ol><blockquote></blockquote><p>&quot;你好&quot;——能回复就成功了</p><blockquote><p>注意：Claude Desktop 和 Claude Code CLI 是<strong>两个独立应用</strong>，配置各管各的。你在 CC Switch 里切了 Desktop，不影响 CLI，反之亦然（两边都要的话，两个面板各加一次、各切一次）。</p></blockquote><p><strong>想切回官方登录？</strong> 在 CC Switch 里选「Claude Desktop Official」，重启客户端即恢复。</p><h2 id="五、常见问题" tabindex="-1">五、常见问题 <a class="header-anchor" href="#五、常见问题" aria-label="Permalink to &quot;五、常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>解决</th></tr></thead><tbody><tr><td>切换了没反应</td><td>必须重启 Claude Desktop 才生效</td></tr><tr><td>报模型不支持</td><td>检查「需要模型映射」开关是否该打开</td></tr><tr><td>找不到 Claude Desktop 入口</td><td>设置 → 通用 → 应用可见性，确认没被隐藏</td></tr><tr><td>导入时被跳过</td><td>模型映射无法判断的供应商会跳过，手动添加</td></tr><tr><td>用 Linux</td><td>暂不支持，用 Claude Code CLI 版</td></tr></tbody></table><h2 id="六、总结" tabindex="-1">六、总结 <a class="header-anchor" href="#六、总结" aria-label="Permalink to &quot;六、总结&quot;">​</a></h2><p>Claude Desktop 接中转站：<strong>下载 CC Switch → Claude Desktop 面板添加（或从 CLI 一键导入）→ 切换 → 重启 Claude Desktop</strong>。桌面版没有内置切换器，CC Switch 这一步逃不掉，但用起来就是&quot;点一下 + 重启&quot;。</p><p>Claude、GPT、Gemini 全家桶一个 Key 通吃？试试 Aklibk API 中转站（ai.aklibk.com），国内直连、免绑卡、人民币按量付费。</p><blockquote><p>下一篇预告：OpenCode 这个开源编程助手的接入教程，同样是小白三步走。</p></blockquote>',30)])])}const k=e(l,[["render",s]]);export{p as __pageData,k as default};
